"""FR-02 owner module: verified metrics computed from validated operands.

Requirement: FR-02. Contracts: C0 (run identity) and C2 (verified metrics),
interface v1.0. Plan revision FR02-PLAN-01.

Public v1 callables (interface-contracts.md, "V1 callable boundaries"):

    verify_metric(request, run) -> MetricResult
    resolve_metric(metric_id, registry, run) -> VerifiedMetric or null

Rules this module enforces, all derived from the contracts rather than from
the callers:

* Every record is scoped to the run that produced it. ``run_id``, ``ticker``
  and ``as_of_date`` are copied from the RunContext, never taken from the
  request or from caller-supplied records.
* Arithmetic uses the original operands exactly (``decimal.Decimal``), so
  operand precision is retained independently of any later display rounding.
  Nothing is rounded to make a computation succeed and nothing is made
  absolute: a signed difference keeps the sign of ``current - reference``.
* YoY and ratio denominators must be greater than zero. A legal negative
  numerator (or a negative current value for YoY) keeps its sign.
* Anything that cannot be verified is refused as UNVERIFIABLE with
  ``metric = None`` and one or more reason codes; a refused request registers
  nothing.
* ``resolve_metric`` only answers an ID this module issued, for this run, and
  whose stored content still matches the trusted record. Unknown, forged,
  cross-run and value-modified IDs resolve to ``None``; a caller-supplied
  replacement value is never accepted.

Records are plain mappings shaped like the C0/C2 tables so the graph can hold
them in state and the analyst adapters can build operands from real tool
returns. This module performs no I/O, calls no model and opens no transport.
"""

from __future__ import annotations

import copy
import hashlib
import json
from decimal import Decimal, InvalidOperation

__all__ = [
    "contract_version",
    "verify_metric",
    "resolve_metric",
    "register_metric",
    "verified_metric_ids",
    "CONTRACT_VERSION",
    "VERIFIED",
    "UNVERIFIABLE",
    "FIELDS",
    "REQUIRED_ROLES",
]

#: Contract revision carried by every record this module issues.
CONTRACT_VERSION = "1.0"
contract_version = CONTRACT_VERSION

VERIFIED = "VERIFIED"
UNVERIFIABLE = "UNVERIFIABLE"

#: C0 RunContext fields copied onto each record, in a deterministic order.
RUN_IDENTITY_FIELDS = ("run_id", "ticker", "as_of_date")

#: C2 VerifiedMetric fields beyond the shared identity.
FIELDS = (
    "contract_version",
    "metric_id",
    "kind",
    "operands",
    "result_value",
    "result_unit",
    "formula",
    "source_refs",
) + RUN_IDENTITY_FIELDS

# --- Reason codes --------------------------------------------------------
# Codes are stable strings so a report can quote them without parsing prose.

REQ_NOT_MAPPING = "REQUEST_NOT_MAPPING"
REQ_KIND_UNKNOWN = "KIND_NOT_SUPPORTED"
REQ_OPERANDS_NOT_LIST = "OPERANDS_NOT_LIST"
REQ_OPERANDS_MISSING = "OPERANDS_MISSING"
REQ_OPERAND_NOT_MAPPING = "OPERAND_NOT_MAPPING"
REQ_ROLES_DUPLICATED = "OPERAND_ROLE_DUPLICATED"
REQ_ROLE_UNEXPECTED = "OPERAND_ROLE_UNEXPECTED"
RUN_IDENTITY_MISSING = "RUN_IDENTITY_MISSING"
RUN_IDENTITY_MISMATCH = "RUN_IDENTITY_MISMATCH"
OPERAND_ROLE_MISSING = "OPERAND_ROLE_MISSING"
OPERAND_VALUE_MISSING = "OPERAND_VALUE_MISSING"
OPERAND_VALUE_NONFINITE = "OPERAND_VALUE_NONFINITE"
OPERAND_UNIT_MISSING = "OPERAND_UNIT_MISSING"
OPERAND_PERIOD_MISSING = "OPERAND_PERIOD_MISSING"
OPERAND_PERIOD_UNORDERED = "OPERAND_PERIOD_END_BEFORE_START"
OPERAND_PERIOD_UNKNOWN = "OPERAND_PERIOD_KIND_UNKNOWN"
OPERAND_FIELD_MISSING = "OPERAND_FIELD_REF_MISSING"
OPERAND_SOURCE_MISSING = "OPERAND_PROVENANCE_MISSING"
PERIODS_NOT_COMPARABLE = "PERIODS_NOT_COMPARABLE"
PERIODS_DIFFERENT = "PERIODS_DIFFERENT"
UNITS_INCOMPATIBLE = "UNITS_INCOMPATIBLE"
DENOMINATOR_NOT_POSITIVE = "DENOMINATOR_NOT_POSITIVE"
COMPUTATION_INVALID = "COMPUTATION_INVALID"

#: Required operand roles per supported kind.
REQUIRED_ROLES = {
    "yoy": ("current", "prior"),
    "ratio": ("numerator", "denominator"),
    "price_delta": ("current", "reference"),
}

#: Formula recorded on each VerifiedMetric.
FORMULAS = {
    "yoy": "100 * (current - prior) / prior",
    "ratio": "100 * numerator / denominator",
    "price_delta": "current - reference",
}

#: Roles whose value must be strictly positive for the kind to be verifiable.
REQUIRED_POSITIVE_ROLE = {"yoy": "prior", "ratio": "denominator"}

PERIOD_KINDS = ("quarter", "year", "instant")

#: Tolerance used only to recognise two fiscal periods one year apart.
_ADJACENT_DAY_SLACK = 7

#: Tolerance used only to recognise one quote instant repeated.
_INSTANT_DAY_SLACK = 0

# --- Registry ------------------------------------------------------------
# A run-local, append-only registry of trusted records, keyed by metric_id.
# It stores its own copies, so a caller mutating the structure it handed back
# from verify_metric cannot change what resolve_metric later returns.

_REGISTRY: dict = {}


def _trusted_copy(record):
    return copy.deepcopy(record)


def _canonical(record):
    """A canonical, order-independent rendering of a record's content."""
    return json.dumps(record, sort_keys=True, separators=(",", ":"), default=str)


def _content_key(record):
    return hashlib.sha256(_canonical(record).encode("utf-8")).hexdigest()


def _metric_id(run, kind, operands):
    """A deterministic, opaque ID over this run's identity and the operands.

    The ID is derived from content, so the same run and the same operands
    always yield the same ID and different operands never share one. Callers
    must not infer meaning from its spelling (C0: IDs are opaque).
    """
    seed = {
        "contract_version": CONTRACT_VERSION,
        "run": {field: run.get(field) for field in RUN_IDENTITY_FIELDS},
        "kind": kind,
        "operands": operands,
    }
    return "metric-" + hashlib.sha256(_canonical(seed).encode("utf-8")).hexdigest()[:32]


def verified_metric_ids(run=None):
    """IDs of registered records, for this run when a RunContext is given."""
    ids = sorted(_REGISTRY)
    if run is None:
        return ids
    return [
        metric_id for metric_id in ids
        if _same_run(_REGISTRY[metric_id], run)
    ]


def register_metric(metric):
    """Record a VerifiedMetric returned by verify_metric in the run registry.

    Only records carrying this module's contract version are accepted; the
    registration path is the product's own, so integration code does not need
    to rebuild the registry by hand. Returns the registered metric_id, or
    ``None`` for anything that is not a verified record.
    """
    if not isinstance(metric, dict):
        return None
    metric_id = metric.get("metric_id")
    if metric.get("contract_version") != CONTRACT_VERSION or not metric_id:
        return None
    stored = _trusted_copy(metric)
    _REGISTRY[metric_id] = stored
    return metric_id


# --- Small readers -------------------------------------------------------


def _as_mapping(value):
    return isinstance(value, dict)


def _text(value):
    """Nonempty stripped text, or None."""
    if not isinstance(value, str):
        return None
    value = value.strip()
    return value or None


def _finite_decimal(value):
    """The operand value as an exact, finite Decimal, or None.

    ``bool`` is refused even though it is an ``int`` subclass, and floats are
    stringified once so binary representation error is not introduced by this
    module. Strings keep every digit they carry.
    """
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, Decimal):
        number = value
    elif isinstance(value, int):
        number = Decimal(value)
    elif isinstance(value, float):
        number = Decimal(repr(value))
    elif isinstance(value, str):
        text = value.strip()
        if not text:
            return None
        try:
            number = Decimal(text)
        except (InvalidOperation, ValueError):
            return None
    else:
        return None
    if not number.is_finite():
        return None
    return number


def _decimal_text(number):
    """A decimal string that keeps the computed value instead of rounding it."""
    text = format(number, "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    if text in ("", "-0"):
        text = "0"
    return text


def _unit_measure(unit):
    """Split a unit into a scale prefix and a dimension, per C2.

    ``USD_millions`` and ``EUR_millions`` share the ``_millions`` scale but are
    different dimensions. USD, USD_millions, EUR_millions and shares are all
    distinct dimensions; a missing or blank unit has no dimension at all.
    """
    text = _text(unit)
    if text is None:
        return None
    lowered = text.lower()
    for scale in ("_millions", "_thousands", "_billions", "_mm", "_mn"):
        if lowered.endswith(scale) and len(lowered) > len(scale):
            return (scale.lstrip("_"), text[: -len(scale)])
    return ("", text)


def _units_compatible(left, right):
    left_measure, right_measure = _unit_measure(left), _unit_measure(right)
    if left_measure is None or right_measure is None:
        return False
    return left_measure == right_measure


def _iso_date(value):
    """A YYYY-MM-DD date as an ordinal day number, or None."""
    text = _text(value)
    if text is None:
        return None
    parts = text.split("-")
    if len(parts) != 3 or not all(part.isdigit() for part in parts):
        return None
    year, month, day = (int(part) for part in parts)
    if not (1 <= month <= 12 and 1 <= day <= 31):
        return None
    try:
        import datetime

        return datetime.date(year, month, day).toordinal()
    except ValueError:
        return None


def _period_span(period):
    """(kind, start ordinal, end ordinal) or a reason code."""
    if not _as_mapping(period):
        return OPERAND_PERIOD_MISSING
    kind = _text(period.get("kind"))
    if kind is None:
        return OPERAND_PERIOD_MISSING
    if kind not in PERIOD_KINDS:
        return OPERAND_PERIOD_UNKNOWN
    start, end = _iso_date(period.get("start")), _iso_date(period.get("end"))
    if start is None or end is None:
        return OPERAND_PERIOD_MISSING
    if end < start:
        return OPERAND_PERIOD_UNORDERED
    return (kind, start, end)


def _periods_comparable(prior_span, current_span):
    """Two YoY periods are comparable when they are one year apart.

    A full year is comparable with the full year before it; a fiscal quarter
    is comparable with the same quarter a year earlier. Anything else (a
    different kind, or a year that is not adjacent) is not compared.
    """
    prior_kind, prior_start, prior_end = prior_span
    current_kind, current_start, current_end = current_span
    if prior_kind != current_kind:
        return False
    if prior_kind == "instant":
        return abs(current_end - prior_end) <= _INSTANT_DAY_SLACK
    # A year apart: compare each boundary with the same boundary one year on.
    if not (1 <= prior_end - prior_start and current_end - current_start):
        return False
    forward = (current_end > prior_end) and _about_one_year(prior_end, current_end)
    return forward and _about_one_year(prior_start, current_start)


def _about_one_year(earlier_ordinal, later_ordinal):
    """True when the later date is the earlier date plus roughly one year."""
    import datetime

    earlier = datetime.date.fromordinal(min(earlier_ordinal, later_ordinal))
    later = datetime.date.fromordinal(max(earlier_ordinal, later_ordinal))
    try:
        anniversary = earlier.replace(year=earlier.year + 1)
    except ValueError:          # 29 February
        anniversary = earlier.replace(year=earlier.year + 1, day=28)
    return abs((later - anniversary).days) <= _ADJACENT_DAY_SLACK


def _run_identity(run):
    """The three identity fields of a RunContext, or a reason code."""
    if not _as_mapping(run):
        return RUN_IDENTITY_MISSING
    identity = {}
    for field in RUN_IDENTITY_FIELDS:
        value = _text(run.get(field))
        if value is None:
            return RUN_IDENTITY_MISSING
        identity[field] = value
    return identity


def _same_run(record, run):
    identity = _run_identity(run)
    if isinstance(identity, str):
        return False
    return all(record.get(field) == identity[field] for field in RUN_IDENTITY_FIELDS)


# --- Operand validation --------------------------------------------------


def _read_operands(request):
    """Validate the request's operands; return {role: operands} or a code list."""
    operands = request.get("operands")
    if not isinstance(operands, (list, tuple)):
        return [REQ_OPERANDS_NOT_LIST]
    if not operands:
        return [REQ_OPERANDS_MISSING]
    reasons = []
    by_role = {}
    for raw in operands:
        if not _as_mapping(raw):
            reasons.append(REQ_OPERAND_NOT_MAPPING)
            continue
        role = _text(raw.get("role"))
        if role is None:
            reasons.append(OPERAND_ROLE_MISSING)
            continue
        if role in by_role:
            reasons.append(REQ_ROLES_DUPLICATED)
            continue
        value = _finite_decimal(raw.get("value"))
        if value is None:
            reasons.append(
                OPERAND_VALUE_MISSING if _text(raw.get("value")) is None
                else OPERAND_VALUE_NONFINITE)
        if _text(raw.get("unit")) is None:
            reasons.append(OPERAND_UNIT_MISSING)
        span = _period_span(raw.get("period"))
        if isinstance(span, str):
            reasons.append(span)
        if _text(raw.get("field_ref")) is None:
            reasons.append(OPERAND_FIELD_MISSING)
        if _text(raw.get("source_ref")) is None:
            reasons.append(OPERAND_SOURCE_MISSING)
        by_role[role] = raw
    ordered = {}
    for role, raw in by_role.items():
        ordered[role] = {
            "role": role,
            "value": value_of := raw.get("value"),
            "unit": raw.get("unit"),
            "period": copy.deepcopy(raw.get("period")),
            "source_ref": _text(raw.get("source_ref")),
            "field_ref": _text(raw.get("field_ref")),
            "_decimal": _finite_decimal(raw.get("value")),
            "_span": _period_span(raw.get("period")),
            "_value_text": value_of,
        }
    return ordered if not reasons else _dedupe(reasons)


def _dedupe(reasons):
    seen = []
    for reason in reasons:
        if reason not in seen:
            seen.append(reason)
    return seen


def _public_operand(operand):
    """The C2 Operand shape, without this module's private reading aids."""
    return {
        "role": operand["role"],
        "value": operand["_value_text"],
        "unit": operand["unit"],
        "period": copy.deepcopy(operand["period"]),
        "source_ref": operand["source_ref"],
        "field_ref": operand["field_ref"],
    }


def _validate_pairing(kind, by_role, reasons):
    """Kind-specific period and unit rules; appends to ``reasons`` in place."""
    roles = REQUIRED_ROLES[kind]
    for role in roles:
        if role not in by_role:
            reasons.append(OPERAND_ROLE_MISSING)
    for role in by_role:
        if role not in roles:
            reasons.append(REQ_ROLE_UNEXPECTED)
    if any(role not in by_role for role in roles):
        return False

    for role in roles:
        if by_role[role]["_decimal"] is None:
            return False

    left, right = by_role[roles[0]], by_role[roles[1]]
    if not _units_compatible(left["unit"], right["unit"]):
        reasons.append(UNITS_INCOMPATIBLE)

    if kind == "yoy":
        if not _periods_comparable(right["_span"], left["_span"]):
            reasons.append(PERIODS_NOT_COMPARABLE)
    elif kind == "ratio":
        if left["_span"] != right["_span"]:
            reasons.append(PERIODS_DIFFERENT)
    else:   # price_delta: one quote instant for both operands
        if left["_span"] != right["_span"]:
            reasons.append(PERIODS_DIFFERENT)
    return not reasons


def _compute(kind, by_role):
    """The exact result Decimal, or a reason code list."""
    roles = REQUIRED_ROLES[kind]
    if kind == "yoy":
        current, prior = by_role["current"]["_decimal"], by_role["prior"]["_decimal"]
        if prior <= 0:
            return [DENOMINATOR_NOT_POSITIVE]
        return Decimal(100) * (current - prior) / prior, "%"
    if kind == "ratio":
        numerator = by_role["numerator"]["_decimal"]
        denominator = by_role["denominator"]["_decimal"]
        if denominator <= 0:
            return [DENOMINATOR_NOT_POSITIVE]
        return Decimal(100) * numerator / denominator, "%"
    current = by_role["current"]["_decimal"]
    reference = by_role["reference"]["_decimal"]
    return current - reference, by_role["current"]["unit"]


def _metric_result(status, metric, reason_codes):
    return {
        "contract_version": CONTRACT_VERSION,
        "status": status,
        "metric": metric,
        "reason_codes": list(reason_codes),
    }


def _unverifiable(reasons):
    return _metric_result(UNVERIFIABLE, None, _dedupe(reasons) or [REQ_OPERANDS_MISSING])


# --- Public boundary -----------------------------------------------------


def verify_metric(request, run):
    """Compute one metric from validated operands and register it when verified.

    Args:
        request: a C2 MetricRequest, ``{"kind", "operands"}``, with operands in
            the C2 Operand shape (role, value, unit, period, source_ref,
            field_ref). Read only.
        run: a C0 RunContext; ``run_id``, ``ticker`` and ``as_of_date`` are
            copied onto the record and scope it to this run. Read only.

    Returns:
        A C2 MetricResult. ``VERIFIED`` carries a VerifiedMetric and no reason
        codes; ``UNVERIFIABLE`` carries ``metric = None`` and at least one
        reason code. A refused request registers nothing.
    """
    if not _as_mapping(request):
        return _unverifiable([REQ_NOT_MAPPING])
    kind = _text(request.get("kind"))
    if kind is None or kind not in REQUIRED_ROLES:
        return _unverifiable([REQ_KIND_UNKNOWN])

    identity = _run_identity(run)
    if isinstance(identity, str):
        return _unverifiable([identity])

    operands = _read_operands(request)
    if isinstance(operands, list):
        return _unverifiable(operands)

    reasons = []
    if not _validate_pairing(kind, operands, reasons):
        return _unverifiable(reasons)

    outcome = _compute(kind, operands)
    if isinstance(outcome, list):
        return _unverifiable(outcome)
    value, unit = outcome
    if not value.is_finite():
        return _unverifiable([COMPUTATION_INVALID])

    ordered = [_public_operand(operands[role]) for role in REQUIRED_ROLES[kind]]
    sources = []
    for operand in ordered:
        if operand["source_ref"] not in sources:
            sources.append(operand["source_ref"])

    metric = {
        "contract_version": CONTRACT_VERSION,
        "metric_id": _metric_id(identity, kind, ordered),
        "kind": kind,
        "operands": ordered,
        "result_value": _decimal_text(value),
        "result_unit": unit,
        "formula": FORMULAS[kind],
        "source_refs": sources,
    }
    for field in RUN_IDENTITY_FIELDS:
        metric[field] = identity[field]
    metric["content_digest"] = _content_key(
        {key: metric[key] for key in FIELDS})

    register_metric(metric)
    return _metric_result(VERIFIED, _trusted_copy(metric), [])


def resolve_metric(metric_id, registry, run):
    """Resolve a trusted ID to its VerifiedMetric, or ``None``.

    Only an ID this module issued, for the same run, and whose stored content
    still matches what was verified will resolve. Unknown IDs, invented IDs,
    IDs from another run and records whose value or operands were altered all
    return ``None``. A caller-supplied replacement value is never returned.

    ``registry`` may be the module's run-local registry, a mapping of
    metric_id to records, a sequence of records, or ``None``; it is read, never
    trusted over the module's own copy.
    """
    candidate_id = _text(metric_id)
    if candidate_id is None:
        return None
    identity = _run_identity(run)
    if isinstance(identity, str):
        return None

    trusted = _REGISTRY.get(candidate_id)
    if trusted is None:
        return None
    if not _same_run(trusted, run):
        return None
    if trusted.get("contract_version") != CONTRACT_VERSION:
        return None
    if trusted.get("content_digest") != _content_key(
            {key: trusted[key] for key in FIELDS if key in trusted}):
        return None

    offered = _offered_record(candidate_id, registry)
    if offered is not None and _altered(offered, trusted):
        return None
    return _trusted_copy(trusted)


def _offered_record(metric_id, registry):
    """The caller's copy of this ID from its registry, when it has one."""
    if isinstance(registry, dict):
        record = registry.get(metric_id)
        return record if _as_mapping(record) else None
    if isinstance(registry, (list, tuple)):
        for record in registry:
            if _as_mapping(record) and record.get("metric_id") == metric_id:
                return record
    return None


def _altered(offered, trusted):
    """True when the caller's copy differs from the trusted record's content."""
    if offered.get("metric_id") != trusted.get("metric_id"):
        return True
    for key in FIELDS:
        if key not in trusted:
            continue
        if _canonical(offered.get(key)) != _canonical(trusted.get(key)):
            return True
    return False

