#: A full fiscal year is 365 or 366 days; a fiscal quarter about a quarter of
#: that. The bounds allow the ordinary 4-4-5 style variation, not a single day.
_YEAR_MIN_DAYS = 360
_YEAR_MAX_DAYS = 372
_QUARTER_MIN_DAYS = 88
_QUARTER_MAX_DAYS = 95
