def _same_number(left, right):
    """Equal by numbering: "25", "25.0" and "2.5E1" are the same value."""
    try:
        return _finte_decimal(left) == _finte_decimal(right)
    except (AssertionError, ValueError):
        return False


def _verified_metrics_table(report_text):
    """Rows of the ## Verified Metrics table in the report prose, or None.

    Parsed with markdown-it-py's table rule, so only a real Markdown table
    counts. Only the heading ``## Verified Metrics`` outside a fenced block
    starts the search, the table must be inside that section (ending at the
    next heading of the same or higher level), and its header must be exactly
    ``metric_id``, ``value``, ``unit``. A lookalike table elsewhere, or a
    number in body prose, does not qualify.
    """
    from markdown_it import MarkdownIt

    tokens = MarkdownIt("commonmark").enable("table").parse(str(report_text))
    headings = []          # (token index, level, text)
    fences = []            # (start index, end index) of fenced blocks
    for index, token in enumerate(tokens):
        if token.type == "fence":
            fences.append(index)
        elif token.type == "heading_open":
            headings.append((index, int(token.tag.lstrip("h") or 0), ""))
        elif token.type == "inline" and headings and headings[-1][0] == index - 1:
            position, level, _ = headings[-1]
            headings[-1] = (position, level, token.content.strip())

    def fenced(index):
        return any(start <= index <= start + 1 for start in fences)

    for position, level, text in headings:
        if text != "Verified Metrics" or level != 2 or fenced(position):
            continue
        end = len(tokens)
        for other, other_level, _ in headings:
            if other > position and other_level <= level:
                end = other
                break
        for index in range(position, end):
            if tokens[index].type != "table_open":
                continue
            header = _table_header(tokens, index)
            if header != ["metric_id", "value", "unit"]:
                continue
            rows = _table_rows(tokens, index)
            return rows or None
    return None


def _table_header(tokens, table_start):
    """Header cell texts of the table opened at ``table_start``."""
    if table_start + 3 >= len(tokens):
        return []
    if tokens[table_start + 1].type != "thead_open":
        return []
    if tokens[table_start + 2].type != "tr_open":
        return []
    cells = []
    position = table_start + 3
    while position < len(tokens) and tokens[position].type in ("th_open", "inline"):
        if tokens[position].type == "inline":
            cells.append(tokens[position].content.strip())
        position += 1
    return cells


def _table_rows(tokens, table_start):
    """Body rows of one table as {header: cell}, in token order."""
    header = _table_header(tokens, table_start)
    if not header:
        return []
    depth = 0
    rows = []
    row = None
    for token in tokens[table_start:]:
        if token.type == "table_open":
            depth += 1
        elif token.type == "table_close":
            depth -= 1
            if depth == 0:
                break
        elif token.type == "tbody_open":
            row = None
        elif token.type == "tr_open":
            row = {}
        elif token.type == "tr_close":
            if row is not None:
                rows.append(row)
            row = None
        elif token.type == "inline" and row is not None:
            position = len(row)
            if position < len(header):
                row[header[position]] = token.content.strip()
    return rows


def _table_row(table, metric_id):
    """The single table row for this ID, or None."""
    matches = [row for row in table if row.get("metric_id") == metric_id]
    return matches[0] if len(matches) == 1 else None

