    # Sources ride after the table as one comment line, so the table itself is
    # unchanged and a CSV reader that skips comments never sees them. Each entry
    # names this run's ticker and CIK, the cell (fiscal end, span, item), the raw
    # figure with its unit exactly as the filing states it, and the filing that
    # states it. A USD column prints v/1_000_000; the entry keeps v, so the
    # printed cell is a rendering and is never read back as the value.
    entries = []
    for label, end, index, unit, fact_unit, fact in printed:
        if label not in _NOTE_ITEMS:
            continue
        # A source is cited only when the fact's own unit is the unit its column
        # uses and every locating field is present on that same record.
        if fact_unit != unit:
