        if not all(fact.get(field) for field in ("end", "filed", "accn")):
            continue
        if "start" not in fact and "start" in fact is not False and fact.get("start") is None:
            # An instant fact (a balance) has no start; a duration fact without
            # one cannot state its period, so it is not cited.
            if fact_unit == "USD" and "start" not in fact:
                pass
