            "ticker": ticker.upper(), "cik": cik, "as_of": as_of_date,
            "item": label, "period": end, "span": index,
            "tag": tag, "value": fact["val"], "unit": fact_unit,
            "start": fact["start"], "end": fact["end"],
            "filed": fact["filed"], "accn": fact["accn"],
