def _fmt(value) -> str:
    if value is None or pd.isna(value):
        return "N/A"
    if isinstance(value, pd.Timestamp):
        return value.strftime("%Y-%m-%d")
    if isinstance(value, bool):
        return str(value)
    if isinstance(value, (int,)):
        return str(value)
    if isinstance(value, float):
        return price_text(value)
    return str(value)


def _finite_number(value) -> float | None:
    """The value as a finite float, or None when it is missing or not a number."""
    if isinstance(value, bool) or value is None:
        return None
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    return number if math.isfinite(number) else None


def _quote_source(df: pd.DataFrame, stock_df: pd.DataFrame, symbol: str, as_of_date: str) -> dict | None:
    """The quote source for the row this snapshot reports, or None.

    The frame's own ``fr02_quote_source`` must agree on three things before a
    source is published: its stock with ``normalize_symbol(symbol)``, its
    trading day with the newest row actually kept, and a currency that is
    plainly a code rather than a blank or a placeholder. The prices come from
    that row: ``Close`` from ``df`` and ``boll_ub`` from the same row of the
    ``stock_df`` that computed this snapshot. Nothing is re-requested, and a
    ``boll_ub`` that was not computed is not calculated just to fill a source;
    the snapshot simply carries none.
    """
    source = getattr(df, "attrs", {}).get("fr02_quote_source")
    if not isinstance(source, dict):
        return None
    if df.empty or stock_df.empty:
        return None

    canonical = normalize_symbol(symbol)
    stated_symbol = source.get("symbol")
    if not isinstance(stated_symbol, str) or stated_symbol.strip().upper() != canonical.strip().upper():
        return None

    latest_date = df["Date"].iloc[-1]
    if not isinstance(latest_date, pd.Timestamp):
        latest_date = pd.to_datetime(latest_date, errors="coerce")
    if pd.isna(latest_date):
        return None
    stated_date = source.get("latest_trading_date")
    if not isinstance(stated_date, str) or stated_date != latest_date.strftime("%Y-%m-%d"):
        return None

    currency = source.get("currency")
    if not isinstance(currency, str) or not currency.strip():
        return None
    if currency.strip().lower() in {"nan", "none", "null", "n/a", "na", "unknown"}:
        return None

    close = _finite_number(df["Close"].iloc[-1])
    if close is None:
        return None
    if "boll_ub" not in stock_df.columns:
        return None
    upper = _finite_number(stock_df["boll_ub"].iloc[-1])
    if upper is None:
        return None

    return {
        "symbol": canonical,
        "trading_date": latest_date.strftime("%Y-%m-%d"),
        "as_of_date": as_of_date,
        "currency": currency,
        "close": close,
        "boll_ub": upper,
    }


def build_verified_market_snapshot(
    symbol: str,
    as_of_date: str,
    look_back_days: int = 30,
    indicators: Iterable[str] | None = None,
) -> str:
    """Render a ground-truth snapshot: latest OHLCV row, indicators, recent closes."""
    # `df` keeps the original capitalized OHLCV columns (Open/High/Low/Close/
    # Volume); stockstats `wrap()` lowercases columns and adds indicator
    # columns, so read raw prices from `df` and indicators from `stock_df`.
    df = _verified_rows(symbol, as_of_date)
    stock_df = wrap(df.copy())

    selected = tuple(indicators or DEFAULT_SNAPSHOT_INDICATORS)
    indicator_values: dict[str, str] = {}
    for name in selected:
        try:
            stock_df[name]  # triggers stockstats calculation
            indicator_values[name] = _fmt(stock_df.iloc[-1][name])
