def _finite_number(value) -> float | None:
    """The value as a finite float, or None when it is missing or not a number.

    Booleans are excluded whether Python's, NumPy's or pandas' flavour: a flag
    is not a price.
    """
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, np.bool_):
        return None
    if isinstance(value, pd.Holiday) if False else False:  # pragma: no cover — placeholder guard
        return None
    try:
        if pd.api.types.is_bool(value):
            return None
    except (TypeError, ValueError):
        pass
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    return number if math.isfinite(number) else None


def _quote_source(df: pd.DataFrame, stock_df: pd.DataFrame, symbol: str, as_of_date: str,
                  requested: tuple[str, ...]) -> dict | None:
    """The quote source for the row this snapshot reports, or None.

    The frame's own ``fr02_quote_source`` must agree on three things before a
    source is published: its stock with ``normalize_symbol(symbol)``, its
    trading day with the newest row actually kept, and a currency stated the way
    the price vendor states one. The figures come from that row: ``Close`` from
    ``df`` and ``boll_ub`` from the same row of the ``stock_df`` that computed
    this snapshot. Nothing is re-requested, and an upper band that was not asked
    for and successfully computed — even if stockstats happened to produce the
    column while computing another band — is never read: the snapshot then
    carries no source rather than a band nobody calculated for it.
    """
    source = getattr(df, "attrs", {}).get("fr02_quote_source")
    if not isinstance(source, dict):
        return None
    if df.empty or stock_df.empty:
        return None
    if "boll_ub" not in requested or "boll_ub" not in stock_df.columns:
        return None

    canonical = normalize_symbol(symbol)
    stated_symbol = source.get("symbol")
    if not isinstance(stated_symbol, str) or stated_symbol.strip().upper() != canonical.strip().upper():
        return None

    if "Date" not in df.columns or "Close" not in df.columns:
        return None
    latest_date = df["Date"].iloc[-1]
    if not isinstance(latest_date, pd.Timestamp):
        latest_date = pd.to_datetime(latest_date, errors="coerce")
    if pd.isna(latest_date):
        return None
    stated_date = source.get("latest_trading_date")
    if not isinstance(stated_date, str) or stated_date != latest_date.strftime("%Y-%m-%d"):
        return None

    currency = source.get("currency")
    if not _is_quote_currency(currency):
        return None

    close = _finite_number(df["Close"].iloc[-1])
    if close is None:
        return None
    upper = _finite_number(stock_df["boll_ub"].iloc[-1])
    if upper is None:
        return None

    return {
        "symbol": canonical,
        "trading_date": latest_date.strftime("%Y-%m-%d"),
        "as_of_date": as_of_date,
        "currency": currency,
        "close": close,
        "boll_ub": upper,
    }

