# Every target a shared conditional router can return. Each edge driven by the
# router maps all of them, so a fall-through return (e.g. under prompt/i18n/
# refactor drift in the speaker labels) can never hit a missing path_map entry
# and crash LangGraph mid-run (#1088).
DEBATE_PATH_MAP = {
    "Bull Researcher": "Bull Researcher",
    "Bear Researcher": "Bear Researcher",
    "Research Manager": "Research Manager",
}
RISK_ANALYSIS_PATH_MAP = {
    "Aggressive Analyst": "Aggressive Analyst",
    "Conservative Analyst": "Conservative Analyst",
    "Neutral Analyst": "Neutral Analyst",
    "Portfolio Manager": "Portfolio Manager",
}

# The three tools whose replies end in a source line. Everything else the
# analysts call is passed through untouched.
_QUOTE_TOOL = "get_verified_market_snapshot"
_INCOME_TOOL = "get_income_statement"
_CASHFLOW_TOOL = "get_cashflow"
_SOURCE_TOOLS = (_QUOTE_TOOL, _INCOME_TOOL, _CASHFLOW_TOOL)

# The source lines the vendors append: the quote the snapshot was priced with,
# and the facts behind each statement cell. Both are found only at the end of a
# reply, on the tool's own comment line.
_QUOTE_SOURCE_PREFIX = "# FR02_QUOTE_SOURCE "
_STATEMENT_SOURCE_PREFIX = "# FR02_SEC_SOURCE "

# Which statement each tool serves, and which of its rows become metrics.
_YOY_ITEMS = ("Revenue", "Cost of Revenue")

# SEC values are reported in whole units of their own unit; ``display_divisor``
# is what the printed cell divides by. Money is carried as USD_millions.
_MILLIONS = Decimal(1000000)
_QUARTERS = {"Q1": 1, "Q2": 2, "Q3": 3, "Q4": 4}


def _tools_or_done(state) -> str:
    """Route an analyst's turn: run its tool calls, or finish with its report."""
    return "tools" if state["messages"][-1].tool_calls else END


def _successful_replies(messages) -> list:
    """This turn's successful ToolMessages, matched to their own call by name and ID.

    A reply is taken only when a recorded call carries its exact ``tool_call_id``
    and the name matches, when the reply is not an error, and when it is one of
    the three source-bearing tools. Nothing is read from model prose.
    """
    asked = {}
    for message in messages:
        for call in (getattr(message, "tool_calls", None) or []):
            call_id = call.get("id") if isinstance(call, dict) else None
            if call_id:
                asked[call_id] = call.get("name")
    replies = []
    for message in messages:
        if not isinstance(message, ToolMessage):
            continue
        if getattr(message, "status", "success") == "error":
            continue
        call_id = getattr(message, "tool_call_id", None)
        name = getattr(message, "name", None)
        if not call_id or call_id not in asked or asked[call_id] != name:
            continue
        if name not in _SOURCE_TOOLS:
            continue
        replies.append(message)
    return replies


def _source_payload(text, prefix: str):
    """The JSON on the reply's own last source line, or None.

    The line must be the last nonblank one and carry exactly ``prefix``; a
    malformed line reads as no source rather than as a guess.
    """
    lines = [line for line in str(text or "").splitlines() if line.strip()]
    if not lines or not lines[-1].startswith(prefix):
        return None
    try:
        payload = json.loads(lines[-1][len(prefix):])
    except ValueError:
        return None
    return payload if isinstance(payload, list) else None


def _quote_payload(text):
    lines = [line for line in str(text or "").splitlines() if line.strip()]
    if not lines or not lines[-1].startswith(_QUOTE_SOURCE_PREFIX):
        return None
    try:
        payload = json.loads(lines[-1][len(_QUOTE_SOURCE_PREFIX):])
    except ValueError:
        return None
    return payload if isinstance(payload, dict) else None


def _decimal(value):
    """An exact Decimal from a JSON number or a plain numeric string, or None."""
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, str):
        try:
            number = Decimal(value.strip())
        except (InvalidOperation, ValueError):
            return None
    elif isinstance(value, (int, float)):
        number = Decimal(repr(value))
    else:
        return None
    return number if number.is_finite() else None


def _money_value(entry):
    """(value in the fact's own unit, unit with scale) for a statement source entry.

    The raw figure and its stated unit are used, converted by the entry's own
    ``display_divisor`` note: a USD column is printed in millions, so the figure
    becomes ``USD_millions``; any other unit keeps its own name and scale of one.
    """
    raw = _decimal(entry.get("value"))
    unit = entry.get("unit")
    if raw is None or not isinstance(unit, str) or not unit.strip():
        return None, None
    divisor = _decimal(entry.get("display_divisor"))
    if unit == "USD" and divisor:
        return raw / divisor, "USD_millions"
    return raw, unit.strip()


def _period_from_span(entry):
    """A C2 period for a statement fact, or None when its span is unusable.

    A full year is a year; anything else is a quarter, and two periods are only
    paired for a YoY when both are of the same kind and about a year apart — the
    module refuses a half-year counted as a quarter on its own.
    """
    start, end = entry.get("start"), entry.get("end")
    if not all(isinstance(value, str) and value for value in (start, end)):
        return None
    try:
        days = (Decimal(_ordinal(end)) - Decimal(_ordinal(start)) + 1)
    except (InvalidOperation, TypeError, ValueError):
        return None
    kind = "year" if 300 <= days <= 400 else "quarter"
    label = f"{entry.get('item')} {start}..{end}"
    return {"kind": kind, "start": start, "end": end, "label": label}


def _ordinal(iso: str) -> int:
    import datetime

    return datetime.date.fromisoformat(iso).toordinal()


def _statement_ref(entry, tool_name: str) -> str:
    """A source reference naming the filing and period a statement figure came from."""
    return "sec:{}:{}:{}:{}".format(
        entry.get("accn"), entry.get("tag"), entry.get("start"), entry.get("end"))


def _statement_requests(payload, tool_name: str):
    """(kind, operands) pairs for the statement's own figures, each built from one fact.

    Revenue and Cost of Revenue get a YoY over two adjacent same-length
    periods of the same item. The cash-flow statement gets Capex over Operating
    Cash Flow from one shared period, with both signs as filed.
    """
    by_item = {}
    for entry in payload:
        if not isinstance(entry, dict):
            continue
        item = entry.get("item")
        period = entry.get("period")
        if not isinstance(period, str) or not period:
            continue
        value, unit = _money_value(entry)
        if value is None:
            continue
        if not _period_from_span(entry):
            continue
        by_item.setdefault(item, {})[period] = (entry, value, unit)

    def operand(role, entry, value, unit):
        return {
            "role": role,
            "value": str(value),
            "unit": unit,
            "period": _period_from_span(entry),
            "source_ref": _statement_ref(entry, tool_name),
            "field_ref": entry.get("tag"),
        }

    requests = []
    if tool_name == _INCOME_TOOL:
        for item in _YOY_ITEMS:
            rows = by_item.get(item) or {}
            periods = sorted(rows)
            if len(periods) < 2:
                continue
            prior_end, current_end = periods[-2], periods[-1]
            prior, current = rows[prior_end], rows[current_end]
            if prior[2] != current[2]:
                continue
            requests.append(("yoy", [
                operand("current", current[0], current[1], current[2]),
                operand("prior", prior[0], prior[1], prior[2]),
            ]))
    else:
        capex = by_item.get("Capital Expenditure") or {}
        flow = by_item.get("Operating Cash Flow") or {}
        for period in sorted(set(capex) & set(flow)):
            numerator, denominator = capex[period], flow[period]
            if numerator[2] != denominator[2]:
                continue
            requests.append(("ratio", [
                operand("numerator", numerator[0], numerator[1], numerator[2]),
                operand("denominator", denominator[0], denominator[1], denominator[2]),
            ]))
    return requests


def _quote_request(payload):
    """The price gap the snapshot states: its own upper band less its close."""
    close = _decimal(payload.get("close"))
    upper = _decimal(payload.get("boll_ub"))
    currency = payload.get("currency")
    day = payload.get("trading_date")
    if close is None or upper is None or not isinstance(currency, str) or not currency.strip():
        return None
    if not isinstance(day, str) or not day:
        return None
    period = {"kind": "instant", "start": day, "end": day, "label": f"{day} quote"}
    source = "quote:{}:{}".format(payload.get("symbol") or "", day)
    return ("price_delta", [
        {
            "role": "current", "value": str(upper), "unit": currency,
            "period": dict(period), "source_ref": source, "field_ref": "boll_ub",
        },
        {
            "role": "reference", "value": str(close), "unit": currency,
            "period": dict(period), "source_ref": source, "field_ref": "Close",
        },
    ])


def _metrics_from_messages(messages, run):
    """{metric_id: VerifiedMetric} for this turn's successful source-bearing replies."""
    issued = {}
    for message in _successful_replies(messages):
        name = message.name
        if name == _QUOTE_TOOL:
            payload = _quote_payload(message.content)
            built = _quote_request(payload) if payload else None
            candidates = [built] if built else []
        else:
            payload = _source_payload(message.content, _STATEMENT_SOURCE_PREFIX)
            candidates = _statement_requests(payload or [], name)
        for kind, operands in candidates:
            result = verify_metric({"kind": kind, "operands": operands}, run)
            if not isinstance(result, dict) or result.get("status") != VERIFIED:
                continue
            metric = result.get("metric")
            if isinstance(metric, dict) and metric.get("metric_id"):
                issued[metric["metric_id"]] = metric
    return issued


def _is_source_analyst(spec) -> bool:
    """Whether this analyst's tools can produce verified metrics."""
    return any(getattr(tool, "name", None) in _SOURCE_TOOLS for tool in (spec.tools or ()))


def _analyst_graph(spec, agent, max_tool_rounds: int):
    """One analyst as a graph of its own: the model and its tools, on a private message history.

    It returns only its report, so analysts running side by side never write the
    same key, and its tool calls never reach the other analysts' messages. After
    ``max_tool_rounds`` rounds of tool calls it is told to write its report, and
    that turn ends it whatever it answers, so a model that keeps calling tools
    cannot run the graph into its recursion limit (#1420).

    An analyst whose tools carry sources returns this run's verified metrics
    too, keyed by ID: from each successful tool reply, through the same run's
    ``course_run``, on the normal ending and the wrap-up ending alike. The
    tools themselves, the report and the private message history are unchanged.
    """
    output = TypedDict(f"{spec.key.capitalize()}Report", {spec.report_key: str})
    carries_metrics = _is_source_analyst(spec)
    schema = {spec.report_key: str}
    if carries_metrics:
        schema["verified_metrics"] = dict
        output = TypedDict(f"{spec.key.capitalize()}Report", schema)
        output.__annotations__["verified_metrics"] = dict
    graph = StateGraph(AgentState, output_schema=output)
    graph.add_node("agent", agent)
    graph.add_edge(START, "agent")
    if not spec.tools:
        graph.add_edge("agent", END)
        return graph.compile()

    def calls(messages):
        return [call["name"] for m in messages for call in (getattr(m, "tool_calls", None) or [])]

    def rounds(messages) -> int:
        return sum(1 for m in messages if getattr(m, "tool_calls", None))

    def more_or_wrap_up(state) -> str:
        return "wrap_up" if rounds(state["messages"]) >= max_tool_rounds else "agent"

    def wrap_up(state):
        repeated = ", ".join(f"{name} x{n}" for name, n in Counter(calls(state["messages"])).most_common())
        logger.warning("%s used its %d tool rounds (%s); asking for its report",
                       spec.agent_node, max_tool_rounds, repeated)
        return agent({**state, "messages": [*state["messages"], HumanMessage(WRAP_UP)]})

    def finish(state):
        """The analyst's own report, plus this run's verified metrics when it takes part."""
        if not carries_metrics:
            return {}
        run = state.get("course_run")
        if not isinstance(run, dict):
            return {}
        metrics = _metrics_from_messages(state.get("messages") or [], run)
        return {"verified_metrics": metrics} if metrics else {}

    def tool_node(state):
        """The stock tool node's reply, unchanged, then the metrics it supports."""
        update = ToolNode(list(spec.tools)).invoke(state, config=None)
        update = dict(update) if isinstance(update, dict) else {}
        graph_update = finish({**state, **update})
        update.update(graph_update)
        return update

    graph.add_node("tools", tool_node)
    graph.add_node("wrap_up", wrap_up)
    graph.add_conditional_edges("agent", _tools_or_done, ["tools", END])
    graph.add_conditional_edges("tools", more_or_wrap_up, ["agent", "wrap_up"])
    graph.add_edge("wrap_up", END)
    return graph.compile()

